function identificarItemAtivo(rotaAtual: string): string {
  if (
    rotaAtual === 'AdicionarRepertorio' ||
    rotaAtual === 'DetalheRepertorio' ||
    rotaAtual === 'VisualizarArquivo'
  ) {
    return 'Repertorios';
  }

  if (rotaAtual === 'DetalhesEscala') {
    return 'Escalas';
  }

  return rotaAtual;
}

function RenderizarIcone({
  item,
  selecionado,
}: {
  item: ItemNavbar;
  selecionado: boolean;
}): JSX.Element {
  const cor = selecionado ? '#071426' : '#DDE7F5';
  const tamanho = selecionado ? 21 : 19;

  if (item.biblioteca === 'materialCommunity') {
    return (
      <MaterialCommunityIcons
        name={item.nome}
        size={tamanho}
        color={cor}
      />
    );
  }

  if (item.biblioteca === 'material') {
    return (
      <MaterialIcons
        name={item.nome}
        size={tamanho}
        color={cor}
      />
    );
  }

  return (
    <Feather
      name={item.nome}
      size={tamanho}
      color={cor}
    />
  );
}

function ItemNavegacao({
  item,
  selecionado,
  onPress,
}: {
  item: ItemNavbar;
  selecionado: boolean;
  onPress: () => void;
}): JSX.Element {
  const progresso = useRef(
    new Animated.Value(selecionado ? 1 : 0),
  ).current;

  useEffect(() => {
    Animated.spring(progresso, {
      toValue: selecionado ? 1 : 0,
      friction: 7,
      tension: 80,
      useNativeDriver: true,
    }).start();
  }, [selecionado, progresso]);

  const translateY = progresso.interpolate({
    inputRange: [0, 1],
    outputRange: [0, -14],
  });

  const scale = progresso.interpolate({
    inputRange: [0, 1],
    outputRange: [1, 1.1],
  });

  return (
    <TouchableOpacity
      style={estilos.itemNavbar}
      onPress={onPress}
      activeOpacity={0.8}
      accessibilityLabel={item.titulo}
    >
      <Animated.View
        style={[
          estilos.bolhaIcone,
          selecionado
            ? estilos.bolhaSelecionada
            : estilos.bolhaNormal,
          {
            transform: [
              { translateY },
              { scale },
            ],
          },
        ]}
      >
        {selecionado && (
          <>
            <View style={estilos.haloSelecionado} />
            <View style={estilos.reflexoSelecionado} />
          </>
        )}

        <View style={estilos.iconeNavbar}>
          <RenderizarIcone
            item={item}
            selecionado={selecionado}
          />
        </View>
      </Animated.View>
    </TouchableOpacity>
  );
}

function BarraNavegacaoFixa(): JSX.Element | null {
  const navegacao = useNavigation<any>();

  const rotaAtual = useNavigationState(estado => {
    if (!estado || !estado.routes || estado.routes.length === 0) {
      return '';
    }

    return estado.routes[estado.index]?.name || '';
  });

  const itemAtivo = identificarItemAtivo(rotaAtual);

  if (!rotaAtual || rotaAtual === 'SplashLogo') {
    return null;
  }

  function navegarPara(rota: string) {
    if (rota === rotaAtual) {
      return;
    }

    navegacao.navigate(rota);
  }

  return (
    <View
      style={estilos.areaNavbar}
      pointerEvents="box-none"
    >
      <LinearGradient
        colors={[
          'rgba(18,35,57,0.98)',
          'rgba(8,19,34,0.99)',
          'rgba(5,13,25,0.99)',
        ]}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={estilos.navbar}
      >
        <View style={estilos.luzSuperior} />

        <View style={estilos.itensNavbar}>
          {ITENS_NAVBAR.map(item => {
            const selecionado = item.rota === itemAtivo;

            return (
              <ItemNavegacao
                key={item.rota}
                item={item}
                selecionado={selecionado}
                onPress={() => navegarPara(item.rota)}
              />
            );
          })}
        </View>
      </LinearGradient>
    </View>
  );
}

